<template>
  <section class="operations-copy-editor" aria-label="运营文案编辑">
    <div class="copy-editor-intro"><strong>编辑即预览，保存后默认载入</strong><p>这里只编辑展示文案。价格、计费周期、额度与试用资格仍读取业务配置。</p></div>
    <div class="copy-editor-source"><span>{{ state.source }}</span><small>{{ state.filename }}</small><b v-if="dirty">有未保存修改</b><b v-else class="is-saved">已保存</b></div>
    <label class="copy-editor-group">编辑区域<select v-model="group"><option v-for="item in groups" :key="item.id" :value="item.id">{{ item.label }}</option></select></label>
    <label class="copy-editor-search"><span class="sf-visually-hidden">查找文案</span><input v-model="search" type="search" placeholder="查找文案或字段"/></label>
    <div class="copy-editor-fields"><label v-for="field in fields" :key="field.key" class="copy-editor-field" :data-copy-field="field.key"><span>{{ field.label }}</span><textarea :value="state.values[field.key]" :placeholder="field.inherit?state.values[field.inherit]:undefined" :rows="state.values[field.key].length>70||state.values[field.key].includes('\n')?3:2" :aria-invalid="state.errors[field.key]?'true':'false'" :aria-describedby="'copy-note-'+field.key" @input="edit(field.key,$event.target.value)"/><small :id="'copy-note-'+field.key"><em v-if="state.errors[field.key]">{{ state.errors[field.key] }}</em><template v-else>{{ field.inherit?'留空使用通用文案':field.tokens.length?'保留变量 '+field.tokens.join('、'):'支持直接编辑' }}</template><span>{{ count(state.values[field.key]) }} / {{ field.max }}</span></small></label></div>
    <p v-if="!fields.length" class="copy-editor-empty">没有匹配的文案。</p>
    <div class="copy-editor-actions"><button type="button" class="copy-editor-save" :disabled="state.busy||!dirty||hasErrors||state.external" @click="save">{{ state.busy?'正在保存…':'保存配置' }}</button><button type="button" :disabled="state.busy||!dirty" @click="discard">撤销修改</button></div>
    <p v-if="state.status" class="copy-editor-status" role="status">{{ state.status }}</p>
    <div class="copy-editor-files"><button type="button" :disabled="state.busy" @click="exportFile">导出 JSON</button><button type="button" :disabled="state.busy" @click="$refs.file.click()">导入配置</button><button type="button" :disabled="state.busy" @click="reload">{{ dirty?'放弃修改并载入最新':'载入最新' }}</button><input ref="file" type="file" accept=".json,application/json" hidden @change="importFile"/></div>
    <p class="copy-editor-help">本地运行时生成版本文件；线上演示保存在当前浏览器的本地文件中。导出 JSON 可备份或交接，其他浏览器通过导入使用。</p>
  </section>
</template>
<script>
import {catalog,groupsForPage} from '@/copy/copy-model.cjs'
import {copyState,copyDirty,editCopy,discardCopy,saveCopy,exportCopy,importCopy,reloadCopy} from '@/copy/operations-copy'
export default {
  props:{screen:String},data(){return {state:copyState,group:'',search:''}},
  computed:{groups(){return groupsForPage(this.screen)},dirty:copyDirty,hasErrors(){return !!Object.keys(this.state.errors).length},fields(){const contexts={coach:['chat','credits','plan'],plan:['plan'],membership:['allowance'],course:[],program:[],'world-tour':[],'world-tour-detail':[],movement:[],'movement-training':[],result:['result'],weekly:['weekly'],challenge:['challenge']}[this.screen]||[];return catalog.fields.filter(field=>field.group===this.group&&(field.group!=='actions'||contexts.some(context=>field.key.startsWith('actions.'+context+'.')))&&(!this.search||(field.label+' '+field.key+' '+this.state.values[field.key]).toLowerCase().includes(this.search.toLowerCase())))}},
  watch:{screen:{immediate:true,handler(){this.group=this.groups[0]?.id||'';this.search=''}}},
  methods:{count(value){return Array.from(value).length},edit:editCopy,discard:discardCopy,save:saveCopy,exportFile:exportCopy,async reload(){try{await reloadCopy()}catch(error){this.state.status=error.message}},async importFile(event){const file=event.target.files[0];if(!file)return;try{if(file.size>200000)throw Error('配置文件过大。');importCopy(JSON.parse(await file.text()))}catch(error){this.state.status='导入失败：'+error.message}event.target.value=''}}
}
</script>
<style scoped>
.operations-copy-editor{font-family:inherit;margin-top:20px}.copy-editor-intro strong{display:block;font-size:13px;line-height:21px;color:#344155}.copy-editor-source{display:flex;flex-wrap:wrap;gap:5px 10px;background:#f5f7fa;border-radius:8px;padding:12px;margin:16px 0;color:#6d788a;font-size:11px;line-height:18px}.copy-editor-source small{display:block;flex-basis:100%;overflow-wrap:anywhere;font-size:10px}.copy-editor-source b{font-size:10px;color:#bb6a3c;font-weight:500}.copy-editor-source b.is-saved{color:#4f8265}.copy-editor-group{display:grid;gap:8px;font-size:11px;line-height:18px;color:#6d788a}.copy-editor-group select,.copy-editor-search input{box-sizing:border-box;width:100%;min-height:38px;border:1px solid #dce2ea;border-radius:7px;background:white;color:#344155;padding:8px;font-family:inherit;font-size:12px;line-height:18px}.copy-editor-search{display:block;margin:10px 0 18px}.copy-editor-field{display:grid;gap:7px;margin-top:20px}.copy-editor-field>span{font-size:12px;line-height:20px;font-weight:500;color:#455269}.copy-editor-field textarea{box-sizing:border-box;resize:vertical;min-height:62px;max-height:280px;width:100%;border:1px solid #dce2ea;border-radius:7px;background:#fff;padding:9px 10px;color:#344155;font:12px/20px -apple-system,BlinkMacSystemFont,'Segoe UI',Arial,sans-serif}.copy-editor-field textarea:focus{outline:2px solid #e8a6a3;outline-offset:1px}.copy-editor-field textarea[aria-invalid=true]{border-color:#d24c4c}.copy-editor-field small{display:flex;gap:8px;justify-content:space-between;color:#9aa3b2;font-size:10px;line-height:17px}.copy-editor-field small>span{flex:none}.copy-editor-field em{font-style:normal;color:#c24141}.copy-editor-actions{position:sticky;bottom:-24px;z-index:3;display:flex;gap:8px;background:#fff;padding:18px 0 12px;margin-top:20px;border-top:1px solid #edf0f4}.copy-editor-actions button{flex:1;min-height:40px;border:1px solid #dfe5ed;border-radius:7px;color:#607086;background:#fff;font-family:inherit;font-size:12px;line-height:20px;font-weight:500;cursor:pointer}.copy-editor-actions button.copy-editor-save{background:#d82b2d;color:#fff;border-color:#d82b2d}.copy-editor-actions button:disabled{opacity:.4;cursor:default}.copy-editor-status{background:#f5f7fa;border-radius:7px;padding:10px;font-size:11px!important;overflow-wrap:anywhere}.copy-editor-files{display:flex;gap:14px;flex-wrap:wrap;margin:14px 0 0}.copy-editor-files button{border:0;background:transparent;color:#748196;font-size:11px;line-height:20px;min-height:32px;padding:0;cursor:pointer}.copy-editor-help{font-size:10px!important;color:#9aa3b2!important}.copy-editor-empty{padding:24px 0}
</style>
